'use strict';

// MODULES //

var format = require( '@stdlib/string/format' );
var max = require( '@stdlib/math/base/special/fast/max' );
var normalizeString = require( './normalize_string.js' );


// MAIN //

/**
* Normalizes table data.
*
* @private
* @param {string} val - linear data
* @param {string} fmts - format strings
* @param {string} units - width units
* @returns {Collection} modified data buffer
*/
function normalize( val, fmts, units ) {
	var mxWidth;
	var raw;
	var tmp;
	var v;
	var i;

	mxWidth = 0;
	raw = val;

	// Generate a formatted string:
	v = format( fmts, raw );

	// Normalize the string to a data object:
	tmp = normalizeString( v, units );

	// Cache the original datum:
	tmp.raw = raw;
	return tmp;
}


// EXPORTS //

module.exports = normalize;
